input.new_string:
var field = host.parentElement || host;
var pieces = grid.querySelectorAll("img");
var reduced = matchMedia("(prefers-reduced-motion: reduce)");

var IDLE_DELAY = 2000; // ms of stillness before the drift takes back over
var SPEED = 90; // px per second the drifting point travels

var point = { x: -9999, y: -9999 };
var from = point;
var to = point;
var legStart = 0;
var legMs = 0;
var frame;
var loop;
var idleTimer;
var visible = false;

function measure() {
  pieces.forEach(function (el) {
    el.style.setProperty("--x", el.offsetLeft + el.offsetWidth / 2);
    el.style.setProperty("--y", el.offsetTop + el.offsetHeight / 2);
  });
}

function setPoint(x, y) {
  point = { x: x, y: y };
  field.style.setProperty("--mx", x);
  field.style.setProperty("--my", y);
}

function reset() {
  setPoint(-9999, -9999);
}

function track(event) {
  stopDrift();
  clearTimeout(idleTimer);
  idleTimer = setTimeout(startDrift, IDLE_DELAY);

  if (frame) return;
  frame = requestAnimationFrame(function () {
    frame = null;
    // Always relative to the grid, since --x/--y are offsets within it.
    var bounds = grid.getBoundingClientRect();
    setPoint(event.clientX - bounds.left, event.clientY - bounds.top);
  });
}

function leave() {
  clearTimeout(idleTimer);
  if (reduced.matches || !visible) reset();
  else startDrift();
}

// Aim somewhere new, pacing the leg so travel speed stays constant.
function nextLeg(now) {
  from = point;
  to = {
    x: Math.random() * grid.offsetWidth,
    y: Math.random() * grid.offsetHeight,
  };
  legMs = Math.max(
    1200,
    (Math.hypot(to.x - from.x, to.y - from.y) / SPEED) * 1000,
  );
  legStart = now;
}

function drift(now) {
  var t = (now - legStart) / legMs;
  if (t >= 1) {
    nextLeg(now);
    t = 0;
  }
  var e = t * t * (3 - 2 * t); // smoothstep
  setPoint(
    from.x + (to.x - from.x) * e,
    from.y + (to.y - from.y) * e,
  );
  loop = requestAnimationFrame(drift);
}

function startDrift() {
  if (loop || reduced.matches || !visible) return;
  // Pick up from wherever the pointer left off, so there's no jump.
  if (point.x < 0) {
    point = { x: grid.offsetWidth / 2, y: grid.offsetHeight / 2 };
  }
  nextLeg(performance.now());
  loop = requestAnimationFrame(drift);
}

function stopDrift() {
  if (!loop) return;
  cancelAnimationFrame(loop);
  loop = null;
}

measure();
new ResizeObserver(measure).observe(grid);
field.addEventListener("pointermove", track);
field.addEventListener("pointerleave", leave);

// Only burn frames while the hero is actually on screen.
new IntersectionObserver(function (entries) {
  visible = entries[0].isIntersecting;
  if (visible) startDrift();
  else stopDrift();
}).observe(host);

