(async () => {
  const snap = () => { const p = window.__probe(); return { mx: +p.mx.toFixed(1), my: +p.my.toFixed(1), drifting: p.drifting, visible: p.visible, moved: p.scales.filter(s => s > 1.001).length }; };
  const out = [];
  for (let i = 0; i < 5; i++) {
    out.push(snap());
    await new Promise(r => setTimeout(r, 700));
  }
  return out;
})()

(async () => {
  const g = document.getElementById('grid');
  const b = g.getBoundingClientRect();
  const out = [];
  const wait = ms => new Promise(r => setTimeout(r, ms));

  // simulate real pointer movement
  for (let i = 0; i < 4; i++) {
    g.dispatchEvent(new PointerEvent('pointermove', { clientX: b.left + 120 + i*10, clientY: b.top + 150, bubbles: true }));
    await wait(60);
  }
  await wait(100);
  out.push({ phase: 'during pointer', ...(() => { const p = window.__probe(); return { drifting: p.drifting, mx: +p.mx.toFixed(1), my: +p.my.toFixed(1) }; })() });

  // still within idle delay
  await wait(900);
  out.push({ phase: 'idle 1.0s (still under 2s)', drifting: window.__probe().drifting });

  // past idle delay
  await wait(1500);
  const p3 = window.__probe();
  out.push({ phase: 'idle 2.5s', drifting: p3.drifting, mx: +p3.mx.toFixed(1) });

  await wait(700);
  const p4 = window.__probe();
  out.push({ phase: 'idle 3.2s', drifting: p4.drifting, mx: +p4.mx.toFixed(1) });

  return out;
})()

(async () => {
  const wait = ms => new Promise(r => setTimeout(r, ms));
  const spacer = document.createElement('div');
  spacer.style.height = '3000px';
  document.body.appendChild(spacer);
  const out = [{ phase: 'at top', ...window.__probe() && { drifting: window.__probe().drifting, visible: window.__probe().visible } }];
  window.scrollTo(0, 3000);
  await wait(500);
  let p = window.__probe();
  out.push({ phase: 'scrolled away', drifting: p.drifting, visible: p.visible });
  window.scrollTo(0, 0);
  await wait(500);
  p = window.__probe();
  out.push({ phase: 'scrolled back', drifting: p.drifting, visible: p.visible });
  spacer.remove();
  return out;
})()

