  const before = links.map(a => {
    const s = a.querySelector('.strokes');
    return { paths: s.querySelectorAll('path').length, opacity: getComputedStyle(s).opacity };
  });
  // simulate hover on the first
  links[0].dispatchEvent(new MouseEvent('mouseenter'));
  const s0 = links[0].querySelector('.strokes');
  const logo0 = links[0].querySelector('svg:not(.strokes)');
  return {
    before,
    afterEnter: {
      paths: s0.querySelectorAll('path').length,
      viewBox: s0.getAttribute('viewBox'),
      filterId: s0.querySelector('filter')?.id,
      strokeColor: getComputedStyle(s0.querySelector('path')).stroke,
    },
    zIndex: { strokes: getComputedStyle(s0).zIndex, logo: getComputedStyle(logo0).zIndex },
    logoSizing: { width: logo0.getBoundingClientRect().width.toFixed(1) },
    strokesSizing: { width: s0.getBoundingClientRect().width.toFixed(1), height: s0.getBoundingClientRect().height.toFixed(1) },
  };
})()

