python3 - <<'PY'
import re, textwrap

def grab(path, key):
    s = open(path).read()
    i = s.find(key)
    start = s.rfind("<svg", 0, i)
    end = s.find("</svg>", i) + len("</svg>")
    return s[start:end]

raw = {
  "thedistance": (grab("_components/home-contents-main.webc", "the-distance-title"), "The Distance", "0 0 681 136"),
  "summer":      (grab("_components/home-contents-main.webc", "summer-title"),        "Summer",       "0 0 682 122"),
  "rokt":        (grab("_components/home-contents-secondary.webc", "rokt-title"),     "Rokt",         "0 0 295 83"),
}

def paths_of(svg):
    body = svg[svg.find(">")+1:svg.rfind("</svg>")]
    body = re.sub(r'<title[\s\S]*?</title>\s*', '', body)
    return textwrap.dedent(body).strip("\n")

def build_svg(slug, label, viewbox, title_id, indent):
    p = paths_of(raw[slug][0])
    p = "\n".join((" " * indent + "  " + ln.strip()) if ln.strip() else "" for ln in p.splitlines())
    pad = " " * indent
    return (f'{pad}<svg\n'
            f'{pad}  xmlns="http://www.w3.org/2000/svg"\n'
            f'{pad}  fill="currentColor"\n'
            f'{pad}  viewBox="{viewbox}"\n'
            f'{pad}  role="img"\n'
            f'{pad}  aria-labelledby="{title_id}"\n'
            f'{pad}>\n'
            f'{pad}  <title id="{title_id}">{label}</title>\n'
            f'{p}\n'
            f'{pad}</svg>')

meta = {
  "thedistance": dict(comp="the-distance-hero", color="var(--color-charcoal)"),
  "summer":      dict(comp="summer-hero",       color="var(--color-offwhite)"),
  "rokt":        dict(comp="rokt-hero",         color="var(--color-offwhite)"),
}

for slug, m in meta.items():
    svg, label, vb = raw[slug]
    body = build_svg(slug, label, vb, f"title-{slug}-hero", 6)
    out = f'''<div class="hero hero--before-standard hero--offset">
  <div class="contents hero__contents">
    <div class="logo">
{body}
    </div>
  </div>
</div>

<style webc:scoped>
  .hero::before {{
    background-color: var(--color-accent-primary);
  }}

  .contents {{
    color: {m["color"]};
    display: flex;
    justify-content: center;
    padding: 3rem 1.5rem;
  }}

  .logo {{
    max-width: var(--g-max-5);
    width: 100%;

    svg {{
      display: block;
      height: auto;
      width: 100%;
    }}
  }}
</style>
'''
    open(f'_components/{m["comp"]}.webc', "w").write(out)
    print("wrote _components/" + m["comp"] + ".webc")
